entries[7107] = { ["name"] = "Wolfwachenworg beschwören", ["text"] = "Sofort\nBeschwört 0 Wolfwache-Worgs als Begleitung für den Zaubernden bis zur Freigabe." }
entries[7108] = { ["name"] = "Feuchtes Handtuch", ["text"] = "45 Mana\nSofort 1 sek. Abklingzeit\nBannt einen negativen Verzauberungseffekt beim Benutzer. Reinigt mit der Kraft der Zitrone." }
entries[7120] = { ["name"] = "Prachtmeers Verteidigung" }
entries[7121] = { ["name"] = "Antimagischer Schild", ["text"] = "75 Mana 10 Meter Reichweite\nWirken in 2 sek.\nLässt einen Schild aus Antimagie um den Zaubernden herum entstehen und gewährt ihm 10 sec lang Immunität gegen Magie." }
entries[7122] = { ["name"] = "Blutzapfer", ["text"] = "Nahkampfreichweite\nSofort\nZieht 20 Gesundheit von einem Feind ab und heilt den Zaubernden um maximal das Zweifache dieses Wertes." }
entries[7124] = { ["name"] = "Arugals Gabe", ["text"] = "20 Meter Reichweite\nWirken in 2.5 sek.\nFügt einem Feind 5 min lang alle 60 Sek. 175 to 225 Schattenschaden zu." }
entries[7125] = { ["name"] = "Toxinspeichel", ["text"] = "NahkampfreichweiteWirken in 1.5 sek. 1 min Abklingzeit\nFügt einem Feind alle 6 Sek. 17 Naturschaden zu. Entzieht außerdem alle 6 Sek. 20 Mana und überträgt sie auf den Zaubernden. Hält 2 min lang an." }
entries[7126] = { ["name"] = "Handgenähte Lederweste", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Leder (3), Grober Faden\nBrust Leder\n45 Rüstung\nHaltbarkeit 50 / 50\n3" }
entries[7127] = { ["name"] = "Wankelmut", ["text"] = "Nahkampfreichweite\nSofort 1 min Abklingzeit\nErhöht die Zeit zwischen den Angriffen eines Feindes um 25%, verlangsamt sein Zaubertempo um 20% und sein Bewegungstempo um 20%. Hält 1 min lang an." }
entries[7128] = { ["name"] = "Inneres Feuer", ["text"] = "14% von Grundmana\nSofort\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 495 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 30 min lang an oder bis alle 20 Aufladungen verbraucht sind." }
entries[7131] = { ["name"] = "Illusion - Passiv" }
entries[7132] = { ["name"] = "Werwolfirrbild beschwören", ["text"] = "Wirken in 1 sek. 3.333 min Abklingzeit\nBeschwört 2 Werwolfirrbilder, um dem Zaubernden 4 min lang im Kampf zu helfen." }
entries[7133] = { ["name"] = "Feine Lederhose", ["text"] = "Wirken in 12.5 sek.\nReagenzien:\nMittleres Leder (8), Wollstoffballen , Feiner Faden\nFeine Lederhose\nWird beim Anlegen gebunden\nBeine Leder\n69 Rüstung\n+5 Intelligenz\nHaltbarkeit 55 / 55\n16\nAnlegen: Erhöht die Zaubermacht um 5." }
entries[7135] = { ["name"] = "Dunkle Lederhose", ["text"] = "Wirken in 12.5 sek.\nReagenzien:\nMittleres Leder (12), Grauer Farbstoff , Feiner Faden\nDunkle Lederhose\nWird beim Anlegen gebunden\nBeine Leder\n72 Rüstung\n+8 Beweglichkeit\nHaltbarkeit 55 / 55\n18" }
entries[7136] = { ["name"] = "Schattenhafen" }
entries[7137] = { ["name"] = "Schattenaufladung", ["text"] = "Sofort\nStürmt auf einen Gegner zu, erhöht dabei das Tempo und verursacht beim ersten Angriff einen zusätzlichen Schaden von 60." }
entries[7139] = { ["name"] = "Teufelstampfen", ["text"] = "Sofort 20 sek. Abklingzeit\nFügt in der Nähe befindlichen Feinden normalen Schaden plus 20 zu, betäubt sie 3 sec lang und erhöht den von ihnen erlittenen körperlichen Schaden um 10." }
entries[7140] = { ["name"] = "Schwäche aufdecken", ["text"] = "NahkampfreichweiteNächster Nahkampf 25 sek. Abklingzeit\nErhöht 5 sec lang den durch einen Gegner erlittenen körperlichen Schaden." }
entries[7141] = { ["name"] = "Einfacher Teleporter" }
entries[7143] = { ["name"] = "Einfacher Gruppen-Teleporter" }
entries[7144] = { ["name"] = "Steinschlummer", ["text"] = "Sofort\nRuft 15 sec lang die Macht des Steins herbei und macht den Zaubernden immun gegen körperlichen Schaden, aber auch unfähig zu agieren. Während dieser Zeit heilt der Zaubernde alle 3 Sek. 30 Schaden." }
entries[7145] = { ["name"] = "Tauch-Rundschlag", ["text"] = "NahkampfreichweiteNächster Nahkampf 10 sek. Abklingzeit\nFügt einem Feind und seinem nächsten Verbündeten normalen Schaden plus 30 zu, wirkt auf bis zu 3 Ziele." }
entries[7147] = { ["name"] = "Wächterhose", ["text"] = "Wirken in 25 sek.\nReagenzien:\nSchweres Leder (12), Seidenstoffballen (2), Feiner Faden (2)\nWächterhose\nWird beim Anlegen gebunden\nBeine Leder\n85 Rüstung\n+8 Intelligenz\nHaltbarkeit 65 / 65\n27\nAnlegen: Erhöht die Zaubermacht um 9." }
entries[7149] = { ["name"] = "Barbarische Gamaschen", ["text"] = "Wirken in 25 sek.\nReagenzien:\nSchweres Leder (10), Feiner Faden (2), Moosachat\nBarbarische Gamaschen\nWird beim Anlegen gebunden\nBeine Leder\n87 Rüstung\n+6 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 65 / 65\n29\nAnlegen: Erhöht die kritische Trefferwertung um 3." }
entries[7151] = { ["name"] = "Barbarische Schultern", ["text"] = "Wirken in 25 sek.\nReagenzien:\nSchweres Leder (8), Geschmeidiger schwerer Balg , Feiner Faden (2)\nBarbarische Schultern\nWird beim Anlegen gebunden\nSchulter Leder\n76 Rüstung\n+5 Beweglichkeit\n+8 Ausdauer\nHaltbarkeit 50 / 50\n30" }
entries[7153] = { ["name"] = "Wächterumhang", ["text"] = "Wirken in 25 sek.\nReagenzien:\nSchweres Leder (14), Seidenstoffballen (2), Seidenfaden (2)\nWächterumhang\nWird beim Anlegen gebunden\nRücken\n24 Rüstung\n+6 Willenskraft\n32\nAnlegen: Erhöht die Zaubermacht um 6." }
entries[7154] = { ["name"] = "Dunkles Angebot", ["text"] = "180 Gesundheit 10 Meter Reichweite\nSpontanzauber 7 sek. Abklingzeit\nHeilt einen Verbündeten unter Verwendung von dunkler Magie." }
entries[7155] = { ["name"] = "CreatureSpecial" }
entries[7156] = { ["name"] = "Wächterhandschuhe", ["text"] = "Wirken in 25 sek.\nReagenzien:\nSchweres Leder (4), Geschmeidiger schwerer Balg , Seidenfaden\nWächterhandschuhe\nWird beim Anlegen gebunden\nHände Leder\n66 Rüstung\n+8 Intelligenz\nHaltbarkeit 30 / 30\n33\nAnlegen: Erhöht die Zaubermacht um 8." }
entries[7159] = { ["name"] = "Meucheln", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nFügt einem Gegner zusätzlichen Schaden zu, allerdings nur, wenn von hinten angegriffen wird." }
entries[7160] = { ["name"] = "Hinrichten", ["text"] = "NahkampfreichweiteNächster Nahkampf 30 sek. Abklingzeit\nVersucht, einen verwundeten Feind ganz zu erledigen, fügt dabei normalen Schaden plus zusätzlichen Schaden zu. 'Hinrichten' kann nur bei Feinden angewendet werden, die über 20% oder weniger Gesundheit verfügen." }
entries[7162] = { ["name"] = "Erste Hilfe", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nHeilt ein Ziel um den gleichen Wert wie den der maximalen Gesundheit des Zaubernden." }
entries[7164] = { ["name"] = "Verteidigungshaltung", ["text"] = "Sofort 3 min Abklingzeit\nNimmt eine Verteidigungshaltung ein. Hält 3 min lang an." }
entries[7165] = { ["name"] = "Kampfhaltung", ["text"] = "Sofort 3 min Abklingzeit\nNimmt eine ausbalancierte Gefechtshaltung ein, die Wut erzeugt, wenn der Krieger getroffen wird, und gleichzeitig Wutabfall verringert, wenn der Krieger sich nicht im Kampf befindet. Hält until cancelled lang an." }
entries[7178] = { ["name"] = "Wasseratmung", ["text"] = "Sofort 1 sek. Abklingzeit\nDer Anwender kann 30 min lang unter Wasser atmen." }
entries[7179] = { ["name"] = "Elixier der Wasseratmung", ["text"] = "Wirken in 3 sek.\nReagenzien:\nWürgetang , Schwarzmaulöl (2), Leere Phiole\n8\nBenutzen: Der Anwender kann 30 min lang unter Wasser atmen. (3 Sek. Abklingzeit)" }
entries[7181] = { ["name"] = "Großer Heiltrank", ["text"] = "Wirken in 3 sek.\nReagenzien:\nLebenswurz , Königsblut , Verbleite Phiole\n21\nBenutzen: Stellt 455 to 585 Gesundheit wieder her. (1 Min Abklingzeit)" }
entries[7183] = { ["name"] = "Elixier der schwachen Verteidigung", ["text"] = "Wirken in 3 sek.\nReagenzien:\nSilberblatt (2), Leere Phiole\nBenutzen: Erhöht die Rüstung 1 hour lang um 50. Wächterelixier. (3 Sek. Abklingzeit)" }
entries[7184] = { ["name"] = "Kontrollverlust" }
entries[7211] = { ["name"] = "Teufelssaurierhaken", ["text"] = "5 Meter Reichweite\nSofort\nSticht einen Teufelssaurier und vergiftet ihn mit einer großen Dosis Gift." }
entries[7212] = { ["name"] = "Aufmerksam", ["text"] = "100 Meter Reichweite\nSofort\nErhöht Eure Verstohlenheitsentdeckung um 3." }
entries[7213] = { ["name"] = "Riesenmuschelrisotto", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRiesenmuschelfleisch\n25\nBenutzen: Stellt im Verlauf von 27 sec 874.8 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 min lang 8 Ausdauer und Willenskraft." }
entries[7215] = { ["name"] = "Mithrilsporen" }
entries[7216] = { ["name"] = "Eisenschildstachel", ["text"] = "Wirken in 3 sek.\nBenötigt Schild\nBringt einen Eisenstachel an Eurem Schild an, der damit bei jedem Blocken Schaden verursacht." }
entries[7217] = { ["name"] = "Waffengegengewicht" }
entries[7218] = { ["name"] = "Waffengegengewicht", ["text"] = "Wirken in 3 sek.\nBringt ein Gegengewicht an einem Zweihandschwert, einem Zweihandstreitkolben, einer Zweihandaxt oder an einer Stangenwaffe an und erhöht die Tempowertung um 20." }
entries[7219] = { ["name"] = "Immun gegen Entwaffnen", ["text"] = "Immun gegen Entwaffnen." }
entries[7220] = { ["name"] = "Waffenkette", ["text"] = "Wirken in 3 sek.\nBenötigt Nahkampfwaffe\nBringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert. Ist nicht mit ähnlichen Effekten stapelbar." }
entries[7221] = { ["name"] = "Eisenschildstachel", ["text"] = "Wirken in 12.5 sek.\nTools:\nSchmiedehammer\nReagenzien:\nEisenbarren (6), Grober Schleifstein (4)\nBenutzen: Bringt einen Eisenstachel an Eurem Schild an, der damit bei jedem Blocken Schaden verursacht." }
