entries[7223] = { ["name"] = "Goldene Schuppenarmschienen", ["text"] = "Wirken in 25 sek.\nTools:\nSchmiedehammer\nReagenzien:\nStahlbarren (5), Schwerer Schleifstein (2)\nGoldene Schuppenarmschienen\nWird beim Anlegen gebunden\nHandgelenke Kette\n96 Rüstung\n+4 Stärke\n+4 Ausdauer\nHaltbarkeit 35 / 35\n32\nAnlegen: Erhöht Eure Waffenkundewertung um 4." }
