entries[7278] = { ["name"] = "Sammlerschwarm beschwören", ["text"] = "Sofort\nBeschwört 1 Sammlerschwarm, um dem Zaubernden 2 min lang im Kampf zu helfen." }
entries[7279] = { ["name"] = "Schwarzer Schlick", ["text"] = "Nahkampfreichweite\nWirken in 3 sek.\nErhöht die Zeit zwischen Angriffen in der Nähe befindlicher Feinde um 50% und verlangsamt ihr Bewegungstempo um 30%. Hält 30 sec lang an." }
entries[7285] = { ["name"] = "Horn der Maraudine blasen", ["text"] = "5 Meter Reichweite\nSofort\nDas Kriegshorn der Maraudine platzieren und blasen." }
entries[7289] = { ["name"] = "Schrumpfen", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nVerringert 2 min lang die Stärke und Ausdauer eines Gegners." }
entries[7290] = { ["name"] = "Seelenentzug", ["text"] = "10 Mana 10 Meter Reichweite\nKanalisiert (Wirken in 10 sek.) 1 sek. Abklingzeit\nZieht 10 sec lang insgesamt 10 Gesundheit von einem Feind ab und heilt den Zaubernden um den maximal zweifachen Wert der gestohlenen Gesundheit." }
entries[7293] = { ["name"] = "Zombiegestalt" }
entries[7294] = { ["name"] = "Aura der Vergeltung", ["text"] = "Sofort\nVerursacht bei jedem Feind, der ein Gruppen- oder Schlachtzugsmitglied schlägt, das sich im Umkreis von 40 Metern befindet, 10 Heiligschaden. Spieler können pro Paladin nur jeweils eine Aura besitzen." }
entries[7295] = { ["name"] = "Seelensauger", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nMacht einen Feind 10 sec lang bewegungsunfähig, entzieht 35 Gesundheit und überträgt sie auf den Zaubernden." }
entries[7300] = { ["name"] = "Frostrüstung", ["text"] = "24% von Grundmana\nSofort\nErhöht die Rüstung um 110. Wenn ein Feind den Zaubernden schlägt, kann 5 sec lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 min lang an." }
entries[7301] = { ["name"] = "Frostrüstung", ["text"] = "24% von Grundmana\nSofort\nErhöht die Rüstung um 200. Wenn ein Feind den Zaubernden schlägt, kann 5 sec lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 min lang an." }
entries[7302] = { ["name"] = "Eisrüstung", ["text"] = "24% von Grundmana\nSofort\nErhöht die Rüstung um 290 und den Frostwiderstand um 6. Wenn ein Feind den Zaubernden schlägt, kann 5 sec lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 min lang an." }
entries[7320] = { ["name"] = "Eisrüstung", ["text"] = "24% von Grundmana\nSofort\nErhöht die Rüstung um 380 und den Frostwiderstand um 9. Wenn ein Feind den Zaubernden schlägt, kann 5 sec lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 min lang an." }
entries[7321] = { ["name"] = "Kälte", ["text"] = "30 Meter Reichweite\nSofort\nVerringert das Bewegungstempo des Angreifers um 30% und erhöht die Zeit zwischen seinen Angriffen um 25%." }
entries[7322] = { ["name"] = "Frostblitz", ["text"] = "10% von Grundmana 30 Meter Reichweite\nWirken in 2.6 sek.\nSchleudert einen Frostblitz auf den Feind, der [Quellwert] bis [Quellwert] Frostschaden verursacht und sein Bewegungstempo 7 sec lang um 40% verringert.", ["unresolvedValues"] = true }
entries[7328] = { ["name"] = "Erlösung", ["text"] = "64% von Grundmana 30 Meter Reichweite\nWirken in 10 sek.\nBringt einen Spieler mit 65 Gesundheit und 120 Mana ins Leben zurück. Kann nicht während des Kampfes verwendet werden." }
