entries[7357] = { ["name"] = "Giftiger Stich", ["text"] = "Nahkampfreichweite\nSofort 30 sek. Abklingzeit\nVerursacht alle 3 Sek. Naturschaden bei einem Feind, erhöht die Zeit zwischen seinen Angriffen um 25% und verringert 15 sec lang sein Bewegungstempo." }
entries[7358] = { ["name"] = "Gemütliches Feuer", ["text"] = "Sofort\nErhöht Eure Willenskraft um 8." }
entries[7363] = { ["name"] = "Feuerleuchten", ["text"] = "Sofort 1 sek. Abklingzeit\nErhöht die Willenskraft der in der Nähe befindlichen Gruppenmitglieder um 4." }
entries[7364] = { ["name"] = "Lichtfackel" }
entries[7365] = { ["name"] = "Flasche Gift", ["text"] = "Nahkampfreichweite\nSofort 1 min Abklingzeit\nWirft eine Flasche Gift auf den Feind und fügt ihm 30 sec lang alle 3 Sek. 19 Naturschaden zu." }
entries[7366] = { ["name"] = "Berserkerhaltung", ["text"] = "Sofort\nNimmt eine aggressive Haltung ein, die Wut erzeugt, wenn der Krieger einen Gegner schlägt. Hält 4 min lang an." }
entries[7367] = { ["name"] = "Infizierter Biss", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht alle 5 Sek. Naturschaden bei einem Feind und erhöht 30 sec lang seinen erlittenen körperlichen Schaden." }
entries[7369] = { ["name"] = "Spalten", ["text"] = "20 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nEin weitreichender Angriff, der dem Ziel und\n\nGlyphe 'Spalten'\nseinen nächsten zwei Verbündeten\n\nseinem nächsten Verbündeten Waffenschaden plus 30 zufügt." }
entries[7370] = { ["name"] = "Sturmangriff" }
entries[7372] = { ["name"] = "Kniesehne", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Berserkerhaltung\nVerstümmelt den Feind, wobei 18 Schaden verursacht werden und die Bewegung des Feindes 15 sec lang auf 45% des normalen Tempos verlangsamt wird." }
entries[7373] = { ["name"] = "Kniesehne", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Berserkerhaltung\nVerstümmelt den Feind, wobei 45 Schaden verursacht werden und die Bewegung des Feindes 15 sec lang um 50% verlangsamt wird." }
entries[7376] = { ["name"] = "Verteidigungshaltung - Passiv", ["text"] = "Verringert den aus jeglichen Quellen erlittenen Schaden um 10%. Verringert zugefügten Schaden um 5%.\nErhöht erzeugte Bedrohung um 45%." }
entries[7377] = { ["name"] = "Periodischen Immunschaden nehmen" }
entries[7379] = { ["name"] = "Rache", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Verteidigungshaltung\nFührt einen sofortigen Gegenangriff gegen den Feind aus, der (197 + Attack power * 0.310) bis (239 + Attack power * 0.310) Schaden verursacht. 'Rache' kann nur genutzt werden, wenn der Krieger zuvor einen Angriff blockte, parierte oder ihm auswich." }
entries[7381] = { ["name"] = "Berserkerhaltung - Passiv", ["text"] = "Erhöht Chance auf kritischen Treffer um 3%.\nErhöht jeglichen erlittenen Schaden um 5%.\nVerringert erzeugte Bedrohung um 20%." }
entries[7383] = { ["name"] = "Wasserblase" }
entries[7384] = { ["name"] = "Überwältigen", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nSofortige Überwältigung des Feindes, die Waffenschaden verursacht. Kann nur verwendet werden, nachdem das Ziel ausgewichen ist. Auf 'Überwältigen' kann nicht mit Blocken, Ausweichen oder Parieren reagiert werden." }
entries[7386] = { ["name"] = "Rüstung zerreißen", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nZerreißt die Rüstung des Ziels, verringert sie pro Einsatz von 'Rüstung zerreißen' um 4% und verursacht ein hohes Maß an Bedrohung. Die Bedrohung wird durch Angriffskraft erhöht. Kann bis zu 5-mal angewendet werden. Hält 30 sec lang an." }
entries[7389] = { ["name"] = "Angreifen", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nErhöht 15 sec lang das Angriffstempo des Tiers des Zaubernden um 50%." }
entries[7393] = { ["name"] = "Bruder heilen", ["text"] = "60 Meter Reichweite\nSofort\nHeilt das Ziel um 30000." }
entries[7394] = { ["name"] = "Drehender Streich", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nVerursacht normalen Schaden plus 5 bei in der Nähe befindlichen Feinden." }
entries[7395] = { ["name"] = "Todesminendynamit", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nFügt allen Feinden in einem ausgewählten Gebiet 43 to 57 Feuerschaden zu." }
entries[7396] = { ["name"] = "Lebertran", ["text"] = "Sofort\nErhöht Eure Nahkampftempowertung 30 sec lang um 100." }
entries[7398] = { ["name"] = "Geburt" }
entries[7399] = { ["name"] = "Erschrecken", ["text"] = "Nahkampfreichweite\nSofort\nErschreckt einen Feind und lässt ihn 4 sec lang voller Furcht flüchten. Es kann immer nur jeweils ein einzelnes Ziel mit Schrecken erfüllt werden." }
entries[7400] = { ["name"] = "Spöttischer Schlag", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 2 min Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nEin spottender Angriff, der 31 Schaden und ein mittleres Maß an Bedrohung verursacht. Zwingt das Ziel 6 sec lang dazu, Angriffe auf Euch zu fokussieren." }
entries[7402] = { ["name"] = "Spöttischer Schlag", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 2 min Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nEin spottender Angriff, der 46 Schaden und ein mittleres Maß an Bedrohung verursacht. Zwingt das Ziel 6 sec lang dazu, Angriffe auf Euch zu fokussieren." }
entries[7405] = { ["name"] = "Rüstung zerreißen", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nZerreißt die Rüstung des Ziels, verringert sie pro Einsatz von 'Rüstung zerreißen' um 180 und verursacht ein hohes Maß an Bedrohung. Die Bedrohung wird durch Angriffskraft erhöht. Kann bis zu 5-mal angewendet werden. Hält until cancelled lang an." }
entries[7408] = { ["name"] = "Schwerer Kupferschlägel", ["text"] = "Wirken in 3 sek.\nTools:\nSchmiedehammer\nReagenzien:\nKupferbarren (12), Schwacher Fluxus (2), Leichtes Leder (2)\nSchwerer Kupferschlägel\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n24 - 36 Schaden Tempo 2.80\n(10.71 Schaden pro Sekunde)\n+2 Stärke\n+2 Beweglichkeit\n+2 Ausdauer\nHaltbarkeit 55 / 55\n11" }
entries[7411] = { ["name"] = "Verzauberkunst", ["text"] = "Sofort\nErmöglicht einem Verzauberer, Standard-Gegenstände mit einer maximalen potenziellen Fertigkeit von 75 zu verzaubern. Es werden Staub und Essenzen benötigt, die durch Entzaubern von magischen Gegenständen gefunden wurden." }
